#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ipos = 0, ilen = 0;
static inline int gc() {
    if (ipos == ilen) { ilen = fread(ibuf, 1, sizeof ibuf, stdin); ipos = 0; if (!ilen) return -1; }
    return ibuf[ipos++];
}
static inline int readInt() {
    int c = gc();
    while (c < '0' || c > '9') c = gc();
    int x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return x;
}

int main() {
    int n = readInt();
    vector<int> lower(n), higher(n);
    for (auto& x : lower) x = readInt();
    for (auto& x : higher) x = readInt();
    int low = 1, high = n;
    while (low < high) {
        int target = (low + high + 1) / 2, chosen = 0;
        // Greedy: with `chosen` already picked, this person fits iff both limits allow it.
        for (int i = 0; i < n && chosen < target; i++)
            if (lower[i] >= chosen && higher[i] >= target - 1 - chosen) chosen++;
        if (chosen == target) low = target; else high = target - 1;
    }
    printf("%d\n", low);
}

