package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int32 {
	c, _ := reader.ReadByte()
	for c < '0' || c > '9' {
		c, _ = reader.ReadByte()
	}
	var x int32
	for c >= '0' && c <= '9' {
		x = x*10 + int32(c-'0')
		var err error
		c, err = reader.ReadByte()
		if err != nil {
			break
		}
	}
	return x
}

func main() {
	n := int(readInt())
	lower := make([]int32, n)
	higher := make([]int32, n)
	for i := range lower {
		lower[i] = readInt()
	}
