		target := (low + high + 1) / 2
		var chosen int32
		// Greedy: with `chosen` already picked, this person fits iff both limits allow it.
		for i := 0; i < n && chosen < target; i++ {
			if lower[i] >= chosen && higher[i] >= target-1-chosen {
				chosen++
			}
		}
